import React from 'react';

interface YouTubeEmbedProps {
  embedId: string;
  title: string;
  showControls?: boolean;
  fill?: boolean;
}

const YouTubeEmbed: React.FC<YouTubeEmbedProps> = ({ 
  embedId, 
  title, 
  showControls = false,
  fill = false
}) => {
  // Base parameters for better compatibility
  const baseParams = "rel=0&playsinline=1&enablejsapi=1";

  // background mode: autoplay, muted, loop, no controls
  // standard mode: no autoplay (better for UX), controls on
  const videoSrc = !showControls
    ? `https://www.youtube.com/embed/${embedId}?autoplay=1&mute=1&loop=1&playlist=${embedId}&controls=0&${baseParams}`
    : `https://www.youtube.com/embed/${embedId}?controls=1&${baseParams}`;

  if (fill) {
    return (
      <div className="absolute inset-0 w-full h-full overflow-hidden pointer-events-none">
        <iframe
          className="absolute top-1/2 left-1/2 w-[300%] h-[300%] -translate-x-1/2 -translate-y-1/2 min-w-full min-h-full"
          src={videoSrc}
          title={title}
          frameBorder="0"
          allow="accelerometer; autoplay; clipboard-write; encrypted-media; gyroscope; picture-in-picture; web-share"
          loading="lazy"
        />
      </div>
    );
  }

  return (
    <div className="relative overflow-hidden w-full bg-black aspect-video rounded-lg">
      <iframe
        className="absolute top-0 left-0 w-full h-full"
        src={videoSrc}
        title={title}
        frameBorder="0"
        allow="accelerometer; autoplay; clipboard-write; encrypted-media; gyroscope; picture-in-picture; web-share"
        allowFullScreen
        loading="lazy"
      />
    </div>
  );
};

export default YouTubeEmbed;

