import React from 'react';

interface YouTubeEmbedProps {
  embedId: string;
  title: string;
  showControls?: boolean;
  fill?: boolean;
}

const YouTubeEmbed: React.FC<YouTubeEmbedProps> = ({ 
  embedId, 
  title, 
  showControls = false,
  fill = false
}) => {
  // Construcción manual y limpia de la URL. 
  // Evitamos URLSearchParams para asegurar máxima compatibilidad en el string final.
  // El Error 153 suele ser un rechazo del reproductor HTML5 de YouTube ante parámetros mal formados o bloqueos de dominio.

  let videoSrc = "";
  if (!showControls) {
    // Configuración para el Hero (Inicio): Autoplay, Mute (obligatorio para autoplay), Loop y Sin controles.
    // Importante: playlist=${embedId} es obligatorio para que el loop funcione en reproductores insertados.
    videoSrc = `https://www.youtube.com/embed/${embedId}?autoplay=1&mute=1&loop=1&playlist=${embedId}&controls=0&rel=0&playsinline=1&modestbranding=1`;
  } else {
    // Configuración para Proyectos: Reproducción estándar con controles.
    videoSrc = `https://www.youtube.com/embed/${embedId}?rel=0&playsinline=1&modestbranding=1&controls=1`;
  }

  if (fill) {
    return (
      <div className="absolute inset-0 w-full h-full overflow-hidden pointer-events-none bg-black">
        <iframe
          key={`hero-${embedId}`}
          className="absolute top-1/2 left-1/2 w-[115%] h-[115%] -translate-x-1/2 -translate-y-1/2 min-w-full min-h-full object-cover"
          src={videoSrc}
          title={title}
          frameBorder="0"
          allow="autoplay; encrypted-media; gyroscope; picture-in-picture"
          loading="eager"
        />
      </div>
    );
  }

  return (
    <div className="relative overflow-hidden w-full bg-black aspect-video rounded-lg shadow-xl border border-white/10">
      <iframe
        key={`project-${embedId}`}
        className="absolute top-0 left-0 w-full h-full"
        src={videoSrc}
        title={title}
        frameBorder="0"
        allow="accelerometer; autoplay; clipboard-write; encrypted-media; gyroscope; picture-in-picture"
        allowFullScreen
        loading="lazy"
      />
    </div>
  );
};

export default YouTubeEmbed;

import React from 'react';

interface YouTubeEmbedProps {
  embedId: string;
  title: string;
  showControls?: boolean;
  fill?: boolean;
}

const YouTubeEmbed: React.FC<YouTubeEmbedProps> = ({ 
  embedId, 
  title, 
  showControls = false,
  fill = false
}) => {
  // Obtenemos el origen actual para pasarlo a YouTube. 
  // Esto valida que la petición viene de un dominio autorizado y evita el bloqueo 153.
  const origin = typeof window !== 'undefined' ? window.location.origin : '';

  let videoSrc = '';
  const baseParams = `enablejsapi=1&origin=${origin}&rel=0`;

  if (!showControls) {
    // Modo Hero/Background: 
    // - autoplay=1: Auto-reproducir
    // - mute=1: Obligatorio para autoplay en navegadores modernos
    // - controls=0: Sin interfaz
    // - loop=1: Bucle infinito
    // - playlist=[ID]: Obligatorio para que funcione el loop
    videoSrc = `https://www.youtube.com/embed/${embedId}?${baseParams}&autoplay=1&mute=1&controls=0&loop=1&playlist=${embedId}&playsinline=1&iv_load_policy=3`;
  } else {
    // Modo Proyecto:
    // - controls=1: Interfaz completa
    videoSrc = `https://www.youtube.com/embed/${embedId}?${baseParams}&controls=1&showinfo=0`;
  }

  if (fill) {
    return (
      <div className="absolute inset-0 w-full h-full overflow-hidden bg-black pointer-events-none">
        <div className="absolute top-1/2 left-1/2 w-[177.77vh] min-w-full min-h-full -translate-x-1/2 -translate-y-1/2">
          {/* El contenedor interior mantiene el ratio 16:9 y cubre la pantalla */}
          <iframe
            key={embedId}
            className="w-full h-full"
            src={videoSrc}
            title={title}
            allow="accelerometer; autoplay; clipboard-write; encrypted-media; gyroscope; picture-in-picture; web-share"
            referrerPolicy="strict-origin-when-cross-origin"
            loading="eager"
            style={{ border: 0 }}
          />
        </div>
        {/* Capa de seguridad para evitar interacción en modo fill */}
        <div className="absolute inset-0 z-10" />
      </div>
    );
  }

  return (
    <div className="relative w-full aspect-video bg-black rounded-lg overflow-hidden shadow-xl border border-white/5">
      <iframe
        key={embedId}
        className="absolute top-0 left-0 w-full h-full"
        src={videoSrc}
        title={title}
        allow="accelerometer; autoplay; clipboard-write; encrypted-media; gyroscope; picture-in-picture; web-share"
        allowFullScreen
        referrerPolicy="strict-origin-when-cross-origin"
        loading="lazy"
        style={{ border: 0 }}
      />
    </div>
  );
};

export default YouTubeEmbed;

import React from 'react';

interface YouTubeEmbedProps {
  embedId: string;
  title: string;
  showControls?: boolean;
  fill?: boolean;
}

const YouTubeEmbed: React.FC<YouTubeEmbedProps> = ({ 
  embedId, 
  title, 
  showControls = false,
  fill = false
}) => {
  // Solución Error 153:
  // 1. Usar www.youtube.com (el dominio nocookie a menudo es bloqueado por políticas de privacidad estrictas).
  // 2. Construcción de string directa para evitar codificación de URLSearchParams.
  // 3. referrerPolicy="strict-origin-when-cross-origin" es obligatorio para autenticar la petición de embed.

  let src = `https://www.youtube.com/embed/${embedId}?`;

  if (!showControls) {
    // Configuración HERO (Fondo):
    // autoplay=1 & mute=1: Obligatorios juntos.
    // loop=1 & playlist={id}: Obligatorios para bucle.
    // controls=0: Ocultar interfaz.
    // disablekb=1: Desactivar atajos de teclado.
    src += `autoplay=1&mute=1&controls=0&loop=1&playlist=${embedId}&playsinline=1&disablekb=1&fs=0&rel=0`;
  } else {
    // Configuración ESTÁNDAR:
    src += `controls=1&rel=0&playsinline=1`;
  }

