import React, { useEffect, useState } from 'react';

interface YouTubeEmbedProps {
  embedId: string;
  title: string;
  showControls?: boolean;
  fill?: boolean;
}

const YouTubeEmbed: React.FC<YouTubeEmbedProps> = ({ 
  embedId, 
  title, 
  showControls = false,
  fill = false
}) => {
  const [iframeSrc, setIframeSrc] = useState<string>('');
  const cleanEmbedId = embedId.trim();

  useEffect(() => {
    // Construimos los parámetros en el cliente para asegurar que 'origin'
    // coincida exactamente con el dominio actual, solucionando el Error 153.
    const params = new URLSearchParams();

    // Ajustes básicos
    params.append('autoplay', showControls ? '0' : '1');
    params.append('mute', showControls ? '0' : '1');
    params.append('controls', showControls ? '1' : '0');
    params.append('playsinline', '1');
    params.append('rel', '0');
    params.append('iv_load_policy', '3');
    params.append('modestbranding', '1');

    // Solución Error 153:
    // Habilitamos la API JS explícitamente y pasamos el origen real.
    params.append('enablejsapi', '1');

    // Solo añadimos el origen si es válido (no file:// o null)
    if (typeof window !== 'undefined' && window.location.origin && window.location.origin !== 'null') {
      params.append('origin', window.location.origin);
    }

    if (!showControls) {
      // Configuración Modo Hero (Fondo)
      params.append('loop', '1');
      params.append('playlist', cleanEmbedId); // Necesario para loop de un solo video
      params.append('fs', '0');
      params.append('disablekb', '1');
    } else {
      params.append('showinfo', '0');
    }

    setIframeSrc(`https://www.youtube.com/embed/${cleanEmbedId}?${params.toString()}`);
  }, [cleanEmbedId, showControls]);

  const iframeStyle: React.CSSProperties = {
    position: 'absolute',
    top: 0,
    left: 0,
    width: '100%',
    height: '100%',
    border: 0,
  };

  const commonProps = {
    title,
    allow: "accelerometer; autoplay; clipboard-write; encrypted-media; gyroscope; picture-in-picture; web-share",
    referrerPolicy: "strict-origin-when-cross-origin" as const,
    allowFullScreen: true,
  };

  if (fill) {
    return (
      <div 
        className="absolute inset-0 w-full h-full overflow-hidden bg-black pointer-events-none"
        aria-hidden="true"
      >
        <div className="absolute top-1/2 left-1/2 w-[120%] h-[120%] -translate-x-1/2 -translate-y-1/2 min-w-full min-h-full">
          {iframeSrc && (
            <iframe
              key={cleanEmbedId}
              src={iframeSrc}
              {...commonProps}
              style={{ ...iframeStyle, pointerEvents: 'none' }}
              tabIndex={-1}
              aria-hidden="true"
            />
          )}
        </div>
        <div className="absolute inset-0 bg-black/50" />
      </div>
    );
  }

  return (
    <div className="relative w-full aspect-video bg-black rounded-lg overflow-hidden shadow-2xl border border-white/5">
      {iframeSrc ? (
        <iframe
          key={cleanEmbedId}
          src={iframeSrc}
          {...commonProps}
          style={iframeStyle}
          loading="lazy"
          aria-label={`Reproductor de video de YouTube: ${title}`}
        />
      ) : (
        <div className="w-full h-full bg-black animate-pulse" />
      )}
    </div>
  );
};

