import React, { useEffect, useState } from 'react';

interface YouTubeEmbedProps {
  embedId: string;
  title: string;
  showControls?: boolean;
  fill?: boolean;
}

const YouTubeEmbed: React.FC<YouTubeEmbedProps> = ({ 
  embedId, 
  title, 
  showControls = false,
  fill = false
}) => {
  const [iframeSrc, setIframeSrc] = useState<string>('');
  const cleanEmbedId = embedId.trim();

  useEffect(() => {
    // 1. Construcción de URL usando URLSearchParams para codificación segura
    const params = new URLSearchParams();

    // Parámetros de reproducción
    params.append('autoplay', showControls ? '0' : '1');
    params.append('mute', showControls ? '0' : '1');
    params.append('controls', showControls ? '1' : '0');
    params.append('playsinline', '1');
    params.append('rel', '0');
    params.append('iv_load_policy', '3');
    params.append('modestbranding', '1');

    // 2. SOLUCIÓN CRÍTICA ERROR 153: API Handshake
    // Habilitamos la API JS
    params.append('enablejsapi', '1');

    // 3. Origen y Referencia
    // YouTube valida la petición comparando la cabecera 'Referer' con el parámetro 'origin'.
    // Deben coincidir.
    if (typeof window !== 'undefined') {
      const origin = window.location.origin;
      params.append('origin', origin);
      params.append('widget_referrer', window.location.href);
    }

    if (!showControls) {
      // Modo Hero/Fondo
      params.append('loop', '1');
      params.append('playlist', cleanEmbedId);
      params.append('fs', '0');
      params.append('disablekb', '1');
    } else {
      params.append('showinfo', '0');
    }

    // 4. Dominio No-Cookie
    // Usamos youtube-nocookie para minimizar conflictos de privacidad/cookies
    setIframeSrc(`https://www.youtube-nocookie.com/embed/${cleanEmbedId}?${params.toString()}`);

  }, [cleanEmbedId, showControls]);

  const iframeStyle: React.CSSProperties = {
    position: 'absolute',
    top: 0,
    left: 0,
    width: '100%',
    height: '100%',
    border: 0,
  };

  // 5. Props de Seguridad
  const commonProps = {
    title,
    allow: "accelerometer; autoplay; clipboard-write; encrypted-media; gyroscope; picture-in-picture; web-share",
    // CRÍTICO: Esto asegura que el navegador envíe la cabecera 'Referer' a YouTube
    referrerPolicy: "strict-origin-when-cross-origin" as const,
    allowFullScreen: true,
  };

  if (fill) {
    return (
      <div 
        className="absolute inset-0 w-full h-full overflow-hidden bg-black pointer-events-none"
        aria-hidden="true"
      >
        <div className="absolute top-1/2 left-1/2 w-[120%] h-[120%] -translate-x-1/2 -translate-y-1/2 min-w-full min-h-full">
          {iframeSrc && (
            <iframe
              key={cleanEmbedId}
              src={iframeSrc}
              {...commonProps}
              style={{ ...iframeStyle, pointerEvents: 'none' }}
              tabIndex={-1}
              aria-hidden="true"
            />
          )}
        </div>
        <div className="absolute inset-0 bg-black/50" />
      </div>
    );
  }

  return (
    <div className="relative w-full aspect-video bg-black rounded-lg overflow-hidden shadow-2xl border border-white/5">
      {iframeSrc ? (
        <iframe
          key={cleanEmbedId}
          src={iframeSrc}
          {...commonProps}
          style={iframeStyle}
          loading="lazy"
          aria-label={`Reproductor de video de YouTube: ${title}`}
        />
      ) : (
        <div className="w-full h-full bg-surface animate-pulse flex items-center justify-center">
            <span className="sr-only">Cargando reproductor...</span>
        </div>
      )}
    </div>
  );
};

