import React from 'react';

interface YouTubeEmbedProps {
  embedId: string;
  title: string;
  showControls?: boolean;
  fill?: boolean;
  /**
   * Si es true, carga un video conocido (Rick Roll) que permite inserción universal.
   * Úsalo para descartar si el error es del código o de los permisos del video original.
   */
  debugMode?: boolean;
}

const YouTubeEmbed: React.FC<YouTubeEmbedProps> = ({ 
  embedId, 
  title, 
  showControls = false,
  fill = false,
  debugMode = false
}) => {
  // 1. Lógica de Debug: Si hay error 153, activa debugMode para probar con un video seguro.
  // Video seguro: Rick Roll (dQw4w9WgXcQ) o Big Buck Bunny.
  const targetVideoId = debugMode ? 'dQw4w9WgXcQ' : embedId.trim();

  // 2. Construcción de URL "Dumb" (Estática)
  // Eliminamos enablejsapi, origin y widget_referrer para evitar el handshake fallido.
  // Usamos parámetros URL estándar de HTML.
  const params = new URLSearchParams();

  params.append('rel', '0');            // No mostrar videos relacionados ajenos
  params.append('modestbranding', '1'); // Menos branding
  params.append('playsinline', '1');    // iOS inline playback

  if (!showControls) {
    // Configuración Hero / Background
    params.append('autoplay', '1');
    params.append('mute', '1');       // OBLIGATORIO para autoplay
    params.append('controls', '0');   // Ocultar UI
    params.append('loop', '1');       // Bucle
    params.append('playlist', targetVideoId); // Necesario para loop de 1 video
    params.append('fs', '0');         // Sin pantalla completa
    params.append('disablekb', '1');  // Sin teclado
  } else {
    // Configuración Normal
    params.append('controls', '1');
    params.append('showinfo', '0');
  }

  // Usamos el dominio estándar. youtube-nocookie es bueno para privacidad, 
  // pero a veces youtube.com estándar es más permisivo con el referer. 
  // Probamos con el estándar para máxima compatibilidad ahora mismo.
  const src = `https://www.youtube.com/embed/${targetVideoId}?${params.toString()}`;

  const iframeStyle: React.CSSProperties = {
    position: 'absolute',
    top: 0,
    left: 0,
    width: '100%',
    height: '100%',
    border: 0,
  };

  const commonProps = {
    title: debugMode ? `DEBUG MODE: ${title}` : title,
    allow: "accelerometer; autoplay; clipboard-write; encrypted-media; gyroscope; picture-in-picture; web-share",
    // CRÍTICO: Mantenemos la política de referer estricta que sabemos que es correcta.
    referrerPolicy: "strict-origin-when-cross-origin" as const,
    allowFullScreen: true,
  };

  if (fill) {
    return (
      <div 
        className="absolute inset-0 w-full h-full overflow-hidden bg-black pointer-events-none"
        aria-hidden="true"
      >
        <div className="absolute top-1/2 left-1/2 w-[120%] h-[120%] -translate-x-1/2 -translate-y-1/2 min-w-full min-h-full">
            <iframe
              key={targetVideoId} // Key fuerza recarga si cambiamos a debug
              src={src}
              {...commonProps}
              style={{ ...iframeStyle, pointerEvents: 'none' }}
              tabIndex={-1}
              aria-hidden="true"
            />
        </div>
        <div className="absolute inset-0 bg-black/50" />
      </div>
    );
  }

  return (
    <div className="relative w-full aspect-video bg-black rounded-lg overflow-hidden shadow-2xl border border-white/5">
        <iframe
          key={targetVideoId}
          src={src}
          {...commonProps}
          style={iframeStyle}
          loading="lazy"
          aria-label={`Reproductor de video de YouTube: ${title}`}
        />
        {debugMode && (
          <div className="absolute top-0 left-0 bg-red-600 text-white text-xs font-bold px-2 py-1 z-50">
            MODO DEBUG ACTIVADO
          </div>
        )}
    </div>
  );
};

