import React, { useEffect, useState } from 'react';
import ReactPlayer from 'react-player/youtube';

interface YouTubeEmbedProps {
  embedId: string;
  title: string;
  showControls?: boolean;
  fill?: boolean;
  debugMode?: boolean;
}

const YouTubeEmbed: React.FC<YouTubeEmbedProps> = ({ 
  embedId, 
  title, 
  showControls = false,
  fill = false,
  debugMode = false
}) => {
  const [isMounted, setIsMounted] = useState(false);

  // Hook para evitar Hydration Error en Next.js (SSR)
  useEffect(() => {
    setIsMounted(true);
  }, []);

  // ID del video (Real o Rick Roll para debug)
  const videoId = debugMode ? 'dQw4w9WgXcQ' : embedId;
  const url = `https://www.youtube.com/watch?v=${videoId}`;

  // Cálculo seguro del origen para evitar bloqueo 153
  const origin = typeof window !== 'undefined' ? window.location.origin : '';

  // Configuración específica para el modo "Fondo de Pantalla" (Fill)
  const playerProps = fill ? {
    playing: true,
    loop: true,
    muted: true, // Necesario para autoplay en navegadores modernos
    controls: false,
    playsinline: true,
    volume: 0,
  } : {
    playing: false,
    controls: showControls,
    muted: false,
  };

  // Si no estamos en el cliente, mostramos un placeholder negro para evitar saltos de layout
  if (!isMounted) {
    return (
      <div 
        className={`bg-black ${fill ? 'absolute inset-0 w-full h-full' : 'relative w-full aspect-video rounded-lg'}`} 
        aria-label="Cargando reproductor..."
      />
    );
  }

  // Estilos del contenedor
  if (fill) {
    return (
      <div 
        className="absolute inset-0 w-full h-full overflow-hidden bg-black pointer-events-none"
        aria-hidden="true"
      >
        <div className="absolute top-1/2 left-1/2 w-[120%] h-[120%] -translate-x-1/2 -translate-y-1/2 min-w-full min-h-full">
          <ReactPlayer
            url={url}
            width="100%"
            height="100%"
            {...playerProps}
            config={{
              youtube: {
                playerVars: {
                  origin: origin, // CRÍTICO: Autentica el dominio
                  modestbranding: 1,
                  rel: 0,
                  showinfo: 0,
                  iv_load_policy: 3,
                  disablekb: 1,
                  fs: 0,
                },
                embedOptions: {
                  host: 'https://www.youtube-nocookie.com' // Capa extra de privacidad/seguridad
                }
              },
            }}
            style={{ pointerEvents: 'none' }}
          />
        </div>
        <div className="absolute inset-0 bg-black/60" />
      </div>
    );
  }

  return (
    <div className="relative w-full aspect-video bg-black rounded-lg overflow-hidden shadow-2xl border border-white/5">
      <ReactPlayer
        url={url}
        width="100%"
        height="100%"
        {...playerProps}
        title={title}
        config={{
          youtube: {
            playerVars: {
              origin: origin,
              modestbranding: 1,
              rel: 0,
            },
            embedOptions: {
              host: 'https://www.youtube-nocookie.com'
            }
          },
        }}
      />
      {debugMode && (
        <div className="absolute top-0 left-0 bg-red-600 text-white text-xs font-bold px-2 py-1 z-50">
          DEBUG: {videoId}
        </div>
      )}
