            embedId="dHp3YUb1x2I" 
            title="Josep Mira Lozano Showreel" 
            fill={true} 
          />
        </div>

        <div className="relative z-20 p-8">
          <h1 className="text-5xl md:text-7xl font-extrabold text-white tracking-tight leading-tight mb-4 drop-shadow-lg">
            Josep Mira Lozano
          </h1>
          <p className="text-xl md:text-2xl text-gray-200 max-w-3xl mx-auto mb-8 drop-shadow-md">
            Filmmaker y Director de Fotografía creando narrativas visuales que cautivan y emocionan.
          </p>
          <Link
            to="/portfolio"
            className="inline-block bg-brand-accent text-white font-bold text-lg py-3 px-8 rounded-md hover:bg-red-700 transition-all duration-300 transform hover:scale-105 shadow-xl shadow-red-900/20"
