import React from 'react';

interface YouTubeEmbedProps {
  embedId: string;
  title?: string;
  showControls?: boolean;
  fill?: boolean;
}

const YouTubeEmbed: React.FC<YouTubeEmbedProps> = ({ 
  embedId, 
  title = "YouTube video player",
  showControls = false,
  fill = false
}) => {

  // Construcción de parámetros basada en el uso (Fondo vs Normal)
  // Aunque el patrón requiere HTML estricto, debemos diferenciar la URL interna
  // para no silenciar los videos del portfolio.
  const queryParams = fill 
    ? `autoplay=1&mute=1&controls=0&rel=0&playsinline=1&loop=1&playlist=${embedId}`
    : `controls=${showControls ? '1' : '0'}&rel=0&playsinline=1`;

  const videoSrc = `https://www.youtube-nocookie.com/embed/${embedId}?${queryParams}`;

  // PATRÓN SRCDOC (SANDBOX):
  // Definimos un documento HTML completo como string.
  // Esto crea un contexto de navegación virgen donde Next.js no puede interferir.
  const embedHtml = `
<!DOCTYPE html>
<html style="margin:0;padding:0;width:100%;height:100%;overflow:hidden;">
<body style="margin:0;padding:0;width:100%;height:100%;background:black;">
  <iframe 
    style="width:100%;height:100%;border:0;" 
    src="${videoSrc}" 
    title="${title}" 
    frameborder="0" 
    allow="accelerometer; autoplay; clipboard-write; encrypted-media; gyroscope; picture-in-picture; web-share" 
    referrerpolicy="strict-origin-when-cross-origin" 
    allowfullscreen>
  </iframe>
</body>
</html>
  `;

  if (fill) {
    return (
      <div className="absolute inset-0 w-full h-full overflow-hidden bg-black pointer-events-none">
        <div className="absolute top-1/2 left-1/2 w-[120%] h-[120%] -translate-x-1/2 -translate-y-1/2 min-w-full min-h-full">
            {/* El contenedor usa srcDoc para renderizar el HTML aislado */}
            <iframe
              srcDoc={embedHtml}
              style={{ width: '100%', height: '100%', border: 'none' }}
              title={title}
              allow="autoplay" // Necesario en el padre para permitir autoplay en el hijo
            />
        </div>
        <div className="absolute inset-0 bg-black/60" />
      </div>
    );
  }

  return (
    <div className="relative w-full aspect-video bg-black rounded-lg overflow-hidden shadow-2xl border border-white/5">
      <iframe
        srcDoc={embedHtml}
        style={{ width: '100%', height: '100%', border: 'none' }}
        title={title}
        allowFullScreen
      />
    </div>
  );
};

export default YouTubeEmbed;

