import React, { useState } from 'react';

interface YouTubeEmbedProps {
  embedId: string;
  title?: string;
  showControls?: boolean;
  fill?: boolean;
}

const YouTubeEmbed: React.FC<YouTubeEmbedProps> = ({ 
  embedId, 
  title = "YouTube video player",
  showControls = false,
  fill = false
}) => {
  const [showVideo, setShowVideo] = useState(false);

  // Construcción de la URL del thumbnail de alta resolución
  const posterUrl = `https://i.ytimg.com/vi/${embedId}/maxresdefault.jpg`;

  // Construcción de la URL del video para el iframe (solo se usa tras el click)
  // CRÍTICO: autoplay=1 es obligatorio aquí porque el usuario ya ha hecho clic en "Play"
  let videoSrc = `https://www.youtube-nocookie.com/embed/${embedId}?autoplay=1`;

  if (fill) {
    // Si es fondo: Muteado, Loopeado, Sin controles
    videoSrc += `&mute=1&loop=1&playlist=${embedId}&controls=0&playsinline=1&rel=0`;
  } else {
    // Si es video normal: Con controles (o no) y Rel=0
    videoSrc += `&controls=${showControls ? '1' : '0'}&rel=0`;
  }

  // Clases base del contenedor
  const containerClasses = fill
    ? "absolute inset-0 w-full h-full bg-black cursor-pointer group overflow-hidden"
    : "relative w-full aspect-video bg-black rounded-lg overflow-hidden shadow-2xl border border-white/5 cursor-pointer group";

  // --- ESTADO ACTIVO: Renderiza el Iframe Real ---
  if (showVideo) {
    return (
      <div className={fill ? "absolute inset-0 w-full h-full bg-black" : "relative w-full aspect-video bg-black rounded-lg overflow-hidden"}>
        <iframe
          src={videoSrc}
          title={title}
          width="100%"
          height="100%"
          frameBorder="0"
          allow="accelerometer; autoplay; clipboard-write; encrypted-media; gyroscope; picture-in-picture; web-share"
          referrerPolicy="strict-origin-when-cross-origin"
          allowFullScreen
          className="absolute top-0 left-0 w-full h-full"
        />
      </div>
    );
  }

  // --- ESTADO INICIAL (FACHADA): Renderiza Imagen + Botón Play ---
  return (
    <div 
      className={containerClasses}
      onClick={() => setShowVideo(true)}
      aria-label={`Reproducir video: ${title}`}
      role="button"
      tabIndex={0}
      onKeyDown={(e) => {
        if (e.key === 'Enter' || e.key === ' ') {
          setShowVideo(true);
        }
      }}
    >
      {/* Fallback de fondo negro por si la imagen falla */}
      <div className="absolute inset-0 bg-black" />

      {/* Thumbnail */}
      <img
        src={posterUrl}
        alt={title}
        className="absolute inset-0 w-full h-full object-cover opacity-90 group-hover:opacity-100 transition-opacity duration-300"
        loading="lazy"
      />

      {/* Overlay Oscuro para resaltar el botón */}
      <div className="absolute inset-0 bg-black/20 group-hover:bg-black/10 transition-colors duration-300" />

      {/* Botón de Play (Círculo Rojo + Triángulo Blanco) */}
      <div className="absolute top-1/2 left-1/2 transform -translate-x-1/2 -translate-y-1/2 z-10">
        <div className="w-16 h-16 md:w-20 md:h-20 bg-brand-accent rounded-full flex items-center justify-center shadow-lg group-hover:scale-110 group-hover:bg-red-600 transition-all duration-300">
          {/* Triángulo CSS */}
          <div className="w-0 h-0 border-t-[10px] border-t-transparent border-l-[18px] border-l-white border-b-[10px] border-b-transparent ml-1 md:border-t-[12px] md:border-l-[22px] md:border-b-[12px]"></div>
        </div>
      </div>
    </div>
  );
};

export default YouTubeEmbed;

import React, { useEffect, useState } from 'react';

interface YouTubeEmbedProps {
  embedId: string;
  title?: string;
  showControls?: boolean;
  fill?: boolean;
}

const YouTubeEmbed: React.FC<YouTubeEmbedProps> = ({ 
  embedId, 
  title = "YouTube Video",
  fill = false
}) => {
  const [isMounted, setIsMounted] = useState(false);

  // Aseguramos que esto solo corra en el cliente
  useEffect(() => {
    setIsMounted(true);
  }, []);

  if (!isMounted) {
    return <div className="bg-black w-full h-full min-h-[200px]" />;
  }

  // URL Limpia: Sin parámetros, dominio estándar.
  const src = `https://www.youtube.com/embed/${embedId}`;

  // Layout básico para que no rompa el diseño (100% width/height)
  const containerClass = fill 
    ? "absolute inset-0 w-full h-full bg-black" 
    : "relative w-full aspect-video bg-black";

  return (
    <div className={containerClass}>
      <iframe
        width="100%"
        height="100%"
        src={src}
        title={title}
        frameBorder="0"
        allow="autoplay; encrypted-media"
        allowFullScreen
        referrerPolicy="no-referrer"
      />
    </div>
  );
};

export default YouTubeEmbed;
